<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Cosmic Game of Life</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #111323;
      --panel: #1b1f38;
      --panel-light: #272c4d;
      --text: #eef2ff;
      --muted: #9fa9d4;
      --accent: #7c5cff;
      --accent-2: #20e3b2;
      --danger: #ff6688;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 24px;
      background:
        radial-gradient(circle at 20% 10%, #292652 0, transparent 34%),
        radial-gradient(circle at 90% 90%, #173c4c 0, transparent 35%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      width: min(680px, 100%);
      text-align: center;
    }

    h1 {
      margin: 0 0 6px;
      font-size: clamp(2rem, 6vw, 3.4rem);
      letter-spacing: -0.06em;
      color: var(--accent-2);
      text-shadow: 0 0 24px rgba(32, 227, 178, .28);
    }

    .subtitle {
      margin: 0 0 20px;
      color: var(--muted);
      font-size: .95rem;
    }

    .board-wrap {
      display: inline-block;
      padding: 12px;
      border-radius: 22px;
      background: linear-gradient(135deg, #30275b, #172f45);
      box-shadow: 0 18px 60px rgba(0, 0, 0, .42), 0 0 0 1px rgba(255,255,255,.08);
    }

    #life {
      display: block;
      width: 576px;
      height: 576px;
      max-width: 78vw;
      max-height: 78vw;
      min-width: 400px;
      min-height: 400px;
      border-radius: 12px;
      background: #0d1020;
      cursor: crosshair;
      touch-action: none;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
      margin-top: 20px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 11px 19px;
      color: var(--text);
      background: var(--panel-light);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 5px 0 rgba(0,0,0,.25);
      transition: transform .12s ease, filter .12s ease, background .12s ease;
    }

    button:hover { filter: brightness(1.18); }
    button:active {
      transform: translateY(4px);
      box-shadow: 0 1px 0 rgba(0,0,0,.25);
    }

    #play { background: var(--accent); }
    #step { background: #315a85; }
    #random { background: #168d78; }
    #clear { background: #a5405c; }

    .hint {
      margin-top: 15px;
      color: var(--muted);
      font-size: .82rem;
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>✨ Cosmic Life</h1>
    <p class="subtitle">Tiny universes, huge patterns.</p>

    <div class="board-wrap">
      <canvas id="life" aria-label="Conway's Game of Life grid"></canvas>
    </div>

    <div class="controls">
      <button id="step" type="button">⏭ Step</button>
      <button id="play" type="button">▶ Play</button>
      <button id="random" type="button">🎲 Randomize</button>
      <button id="clear" type="button">🧹 Clear</button>
    </div>
    <div class="hint">Click or drag across the stars to paint life.</div>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("life");
      const ctx = canvas.getContext("2d");
      const w = 48;
      const h = 48;
      const size = 576;
      let cells = new Uint8Array(w * h);
      let timer = null;
      let drawing = false;
      let paintValue = 1;
      let lastCell = null;

      function index(x, y) {
        return y * w + x;
      }

      function resizeCanvas() {
        const dpr = window.devicePixelRatio || 1;
        canvas.width = size * dpr;
        canvas.height = size * dpr;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        draw();
      }

      function draw() {
        const rect = canvas.getBoundingClientRect();
        const scale = size / rect.width;
        ctx.clearRect(0, 0, size, size);

        ctx.fillStyle = "#0d1020";
        ctx.fillRect(0, 0, size, size);

        const cellSize = size / w;
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            if (cells[index(x, y)]) {
              const px = x * cellSize;
              const py = y * cellSize;
              ctx.fillStyle = "#20e3b2";
              ctx.shadowColor = "rgba(32, 227, 178, .7)";
              ctx.shadowBlur = 7;
              ctx.beginPath();
              ctx.roundRect(px + 2, py + 2, cellSize - 4, cellSize - 4, 3);
              ctx.fill();
              ctx.shadowBlur = 0;
            }
          }
        }

        ctx.strokeStyle = "rgba(145, 157, 216, .13)";
        ctx.lineWidth = 1;
        for (let i = 0; i <= w; i++) {
          const p = Math.round(i * cellSize) + .5;
          ctx.beginPath();
          ctx.moveTo(p, 0);
          ctx.lineTo(p, size);
          ctx.stroke();
        }
        for (let i = 0; i <= h; i++) {
          const p = Math.round(i * cellSize) + .5;
          ctx.beginPath();
          ctx.moveTo(0, p);
          ctx.lineTo(size, p);
          ctx.stroke();
        }
      }

      function cellAt(event) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((event.clientX - rect.left) / rect.width * w);
        const y = Math.floor((event.clientY - rect.top) / rect.height * h);
        return { x, y };
      }

      function paint(x, y, value) {
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        cells[index(x, y)] = value ? 1 : 0;
        draw();
      }

      function step() {
        const next = new Uint8Array(w * h);
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            let neighbors = 0;
            for (let dy = -1; dy <= 1; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                if (dx === 0 && dy === 0) continue;
                const nx = x + dx;
                const ny = y + dy;
                if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                  neighbors += cells[index(nx, ny)];
                }
              }
            }
            const alive = cells[index(x, y)] === 1;
            next[index(x, y)] = alive
              ? (neighbors === 2 || neighbors === 3 ? 1 : 0)
              : (neighbors === 3 ? 1 : 0);
          }
        }
        cells = next;
        draw();
      }

      function clear() {
        cells.fill(0);
        draw();
      }

      function randomize() {
        for (let i = 0; i < cells.length; i++) {
          cells[i] = Math.random() < 0.28 ? 1 : 0;
        }
        draw();
      }

      window.life = {
        w,
        h,
        get(x, y) {
          if (x < 0 || x >= w || y < 0 || y >= h) return 0;
          return cells[index(x, y)];
        },
        set(x, y, v) {
          if (x < 0 || x >= w || y < 0 || y >= h) return;
          cells[index(x, y)] = v ? 1 : 0;
          draw();
        },
        step,
        clear
      };

      canvas.addEventListener("pointerdown", (event) => {
        event.preventDefault();
        drawing = true;
        canvas.setPointerCapture(event.pointerId);
        const { x, y } = cellAt(event);
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        paintValue = window.life.get(x, y) ? 0 : 1;
        lastCell = `${x},${y}`;
        paint(x, y, paintValue);
      });

      canvas.addEventListener("pointermove", (event) => {
        if (!drawing) return;
        const { x, y } = cellAt(event);
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        const key = `${x},${y}`;
        if (key !== lastCell) {
          lastCell = key;
          paint(x, y, paintValue);
        }
      });

      function stopDrawing() {
        drawing = false;
        lastCell = null;
      }

      canvas.addEventListener("pointerup", stopDrawing);
      canvas.addEventListener("pointercancel", stopDrawing);
      canvas.addEventListener("pointerleave", () => {});

      document.getElementById("step").addEventListener("click", step);
      document.getElementById("clear").addEventListener("click", clear);
      document.getElementById("random").addEventListener("click", randomize);

      document.getElementById("play").addEventListener("click", (event) => {
        const button = event.currentTarget;
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
          button.textContent = "▶ Play";
        } else {
          step();
          timer = setInterval(step, 115);
          button.textContent = "⏸ Pause";
        }
      });

      window.addEventListener("resize", resizeCanvas);
      resizeCanvas();
    })();
  </script>
</body>
</html>
